/// The definition [`POSTGRES`] holds, read once.
#[cfg(feature = "postgres")]
pub fn postgres_definition() -> Result<&'static orm::Definition, orm::Error> {
    static DEFINITION: std::sync::OnceLock<Result<orm::Definition, String>> =
        std::sync::OnceLock::new();
    DEFINITION
        .get_or_init(|| orm::Definition::parse(POSTGRES).map_err(|err| err.to_string()))
        .as_ref()
        .map_err(|err| orm::Error::Definition(err.clone()))
}

/// The repositories on Postgres.
#[cfg(feature = "postgres")]
pub mod postgres {
    use super::*;

    pub use orm::postgres::{deadpool_postgres, tokio_postgres};
    use deadpool_postgres::GenericClient;

    /// The repository of `Courier` on a Postgres client.
    pub type CourierRepository<'a, C> =
        orm::postgres::Typed<'a, C, CourierRow, CourierCreate, CourierUpdate, CourierFilter, IdentityUUID>;

    /// The repository of `Delivery` on a Postgres client.
    pub type DeliveryRepository<'a, C> =
        orm::postgres::Typed<'a, C, DeliveryRow, DeliveryCreate, DeliveryUpdate, DeliveryFilter, IdentityUUID>;

    /// The repository of `Depot` on a Postgres client.
    pub type DepotRepository<'a, C> =
        orm::postgres::Typed<'a, C, DepotRow, DepotCreate, DepotUpdate, DepotFilter, IdentityUUID>;

    /// The repository of `Parcel` on a Postgres client.
    pub type ParcelRepository<'a, C> =
        orm::postgres::Typed<'a, C, ParcelRow, ParcelCreate, ParcelUpdate, ParcelFilter, IdentityUUID>;

    /// The tables of `fixture-fenced-db` over `pool`, as a generated router serves
    /// its table operations from them (D106).
    pub fn tables(pool: deadpool_postgres::Pool) -> orm::postgres::Tables {
        orm::postgres::Tables::new(pool, postgres_definition)
    }

    /// The repositories of `fixture-fenced-db` on a Postgres client, acting as a
    /// user or as no one.
    pub struct Repositories<'a, C>(orm::postgres::Repositories<'a, C>);

    impl<'a, C: GenericClient + Sync> Repositories<'a, C> {
        /// The repositories over `client`, the caller's: a connection of
        /// its pool, or a transaction on one. They act as no one until
        /// `acting` names a user.
        pub fn new(client: &'a C) -> Result<Self, orm::Error> {
            orm::postgres::Repositories::new(client, postgres_definition()?).map(Self)
        }

        /// The repositories acting as `user` (D87); `None` acts as no one.
        #[must_use]
        pub fn acting(self, user: Option<String>) -> Self {
            Self(self.0.acting(user))
        }

        /// The repositories acting as the database's system actor (D87).
        #[must_use]
        pub fn as_system(self) -> Self {
            Self(self.0.as_system())
        }

        /// The repositories with the keys of the database's `Encrypted<T>`
        /// fields (D85).
        #[must_use]
        pub fn with_keys(self, keys: &'a dyn orm::FieldKeys) -> Self {
            Self(self.0.with_keys(keys))
        }

        /// The repositories with what runs the behaviors of the tables that
        /// compose them (D103).
        #[must_use]
        pub fn with_rules(self, rules: &'a dyn orm::postgres::Rules<C>) -> Self {
            Self(self.0.with_rules(rules))
        }

        /// The repositories running each behavior's command as `caller`,
        /// whose permissions the core's guards read (D103); the acting
        /// user, holding none, unless set.
        #[must_use]
        pub fn with_caller(self, caller: orm::Caller) -> Self {
            Self(self.0.with_caller(caller))
        }

        /// The repositories telling `trace` each statement's text as it
        /// runs.
        #[must_use]
        pub fn with_trace(self, trace: &'a (dyn Fn(&str) + Sync)) -> Self {
            Self(self.0.with_trace(trace))
        }

        /// The runtime's repositories these are, over JSON objects.
        pub fn untyped(&self) -> &orm::postgres::Repositories<'a, C> {
            &self.0
        }

        /// The repository of `Courier`.
        pub fn courier(&self) -> Result<CourierRepository<'_, C>, orm::Error> {
            self.0.typed("Courier")
        }

        /// The repository of `Delivery`.
        pub fn delivery(&self) -> Result<DeliveryRepository<'_, C>, orm::Error> {
            self.0.typed("Delivery")
        }

        /// The repository of `Depot`.
        pub fn depot(&self) -> Result<DepotRepository<'_, C>, orm::Error> {
            self.0.typed("Depot")
        }

        /// The repository of `Parcel`.
        pub fn parcel(&self) -> Result<ParcelRepository<'_, C>, orm::Error> {
            self.0.typed("Parcel")
        }
    }
}

